import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, } from '@mui/material';
import Iconify from '../../../components/iconify';
import { useMyContext } from '../../provider';
import useResponsive from '../../../hooks/useResponsive';
import InputField from '../../../components/input/inputField';
import GenerateToastConfig from '../../../components/toast-config/GenerateToastConfig';
import { axios } from '../../../utils/axios';

const SubCategoryForm = () => {
    const navigate = useNavigate();
    const { i18 } = useMyContext();
    const location = useLocation();

    const isMobile = useResponsive('down', 'sm');
    const [subCategoryName, setSubCategoryName] = useState('');
    const [subCategoryDesc, setSubCategoryDesc] = useState('');
    const [error, setError] = useState('');
    const [descError, setDescError] = useState('');

    const { subCategoryIds, subCategory, description, EditCategoryId } = location?.state || { subCategoryIds: '', subCategory: '', description: '', EditCategoryId: '' };
    const { categoryId } = location?.state || { categoryId: '' };

    useEffect(() => {
        if(subCategory) setSubCategoryName(subCategory);
        if(description) setSubCategoryDesc(description)
    }, [subCategory, description]);

    const backToRoute = () => {
        navigate(`/dashboard/advSubCategory`, { state: { categoryIds: EditCategoryId || categoryId}});
    };

    const handleSubCategoryChange = (event) => {
        const { value } = event.target;
        if (/^[A-Za-z\s]*$/.test(value)) {
            setSubCategoryName(value);
            if (value.length < 2) {
                setError('Sub-Category is too short');
            } else {
                setError('');
            }
        }
    };

    const handleDescriptionChange = (event) => {
        const { value } = event.target;
        if (/^[A-Za-z\s]*$/.test(value)) {
            setSubCategoryDesc(value);
            if (value.length < 2) {
                setDescError('Description is too short');
            } else {
                setDescError('');
            }
        }
    }

    const addorupdateSubCategory = async () => {
        const formData = new FormData();
        formData.append('subCategory', subCategoryName);
        formData.append('desc', subCategoryDesc);

        try {
            const url = subCategoryIds ? `module/ads/admin/subCategory/${subCategoryIds}` : `module/ads/admin/subCategory/${categoryId}`;
            const method = subCategoryIds ? 'put' : 'post';

            const response = await axios[method](url, formData);

            if (response?.status === 200 || response?.status === 201) {
                GenerateToastConfig(response?.data?.message, 'success');
                backToRoute();
            }
        } catch (error) {
            GenerateToastConfig(error.message, 'error');
        }
    };

    return (
        <>
            <Helmet>
                <title>{subCategoryIds ? 'Edit Sub-Category' : 'Add Sub-Category'}</title>
            </Helmet>
            <Card>
                <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Box
                                sx={{
                                    width: '37px',
                                    height: '37px',
                                    background: '#FF5A60',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    borderRadius: '50%',
                                    cursor: 'pointer',
                                }}
                                onClick={backToRoute}
                            >
                                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
                            </Box>
                            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                {subCategoryIds ? i18?.ACCOUNTSTITLE?.EDIT_SUBCATEGORY || "Edit Sub-Category" : i18?.ACCOUNTSTITLE?.ADD_SUBCATEGORY || "Add Sub-Category"}
                            </Typography>
                        </Box>
                    </Grid>
                </Grid>

                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={subCategoryName}
                            name="subCategoryName"
                            label={i18?.ACCOUNTSTITLE?.SUBCATEGORYNAME || "Sub-Category Name"}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px',
                                },
                            }}
                            onChange={handleSubCategoryChange}
                            type="text"
                            required
                        />
                        {error && <Typography color="error">{error}</Typography>}
                    </Grid>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={subCategoryDesc}
                            name="subCategoryDesc"
                            label={i18?.ACCOUNTSTITLE?.DESCRIPTION || "Descriptiom"}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px',
                                },
                            }}
                            onChange={handleDescriptionChange}
                            type="text"
                            required
                        />
                        {descError && <Typography color="error">{descError}</Typography>}
                    </Grid>
                </Grid>

                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Button
                        sx={{
                            padding: '10px 58px'
                        }}
                        disabled={!subCategoryName || !subCategoryDesc}
                        variant="contained"
                        onClick={addorupdateSubCategory}
                    >
                        {subCategoryIds ? i18?.ACCOUNTSTITLE?.UPDATE || 'Update' : i18?.ACCOUNTSTITLE?.ADD || 'Add'}
                    </Button>
                </Grid>
            </Card>
        </>
    )
}

export default SubCategoryForm
